"""Pruned backtracking search for maximum Sidon sets with the Erdos-Turan cutoff.

A subset A of Z_N is Sidon when all differences a - b (a != b) are distinct modulo N.
The search below enumerates Sidon sets in lexicographic order, maintaining the set of
used differences incrementally, and prunes with two certificates:

  * the sharp all-translate bound  |A|(|A| - 1) <= N - 1, which caps the target size;
  * a look-ahead bound: if the current set cannot be extended to the target size using
    the remaining residues, the branch is abandoned.

Complexity: the difference bookkeeping makes each extension O(|A|); the pruning by the
all-translate bound caps the depth at 1/2 + sqrt(N - 3/4), so the search tree has depth
O(sqrt(N)) instead of O(N).
"""

from __future__ import annotations

from math import isqrt
from typing import List, Set


def erdos_turan_cap(n: int) -> int:
    """Largest m with m(m-1) <= n-1: the sharp cap on a Sidon set in a group of order n."""
    m = 0
    while (m + 1) * m <= n - 1:
        m += 1
    return m


def _extend(
    n: int,
    current: List[int],
    used: Set[int],
    start: int,
    target: int,
    best: List[int],
) -> None:
    if len(current) == target:
        best.clear()
        best.extend(current)
        return
    for x in range(start, n):
        if n - x < target - len(current):
            return                                  # not enough residues left
        fresh: Set[int] = set()
        ok = True
        for y in current:
            for d in ((x - y) % n, (y - x) % n):
                if d in used or d in fresh:
                    ok = False
                    break
                fresh.add(d)
            if not ok:
                break
        if ok:
            current.append(x)
            used |= fresh
            _extend(n, current, used, x + 1, target, best)
            used -= fresh
            current.pop()
            if best:
                return


def maximum_sidon_set(n: int) -> List[int]:
    """A largest Sidon set in Z_N found by pruned backtracking (exact for small N)."""
    cap = erdos_turan_cap(n)
    for target in range(cap, 0, -1):
        best: List[int] = []
        if target == 1:
            return [0]
        _extend(n, [0], set(), 1, target, best)
        if best:
            return best
    return []


def certificate(n: int, a: List[int]) -> str:
    """Human-readable certificate that `a` respects the all-translate bound."""
    m = len(a)
    return (
        f"|A| = {m},  |A|(|A|-1) = {m * (m - 1)} <= {n - 1} = N - 1   "
        f"[cap {erdos_turan_cap(n)}, floor sqrt(N) = {isqrt(n)}]"
    )


if __name__ == "__main__":
    for n in (13, 21, 31, 57, 73):
        a = maximum_sidon_set(n)
        print(f"Z_{n}: {a}")
        print("   " + certificate(n, a))

