        print(f"  {name:<{width}}  {count:4d}/{trials}  {status}")

    print("\n  Sharpness data:")
    sharp: List[Set[int]] = [{0}, {0}]
    print(
        f"    A0 = A1 = {{0}}:  P = {pair_sum(sharp)},  |D| = {double_collisions(sharp)}"
        f"   ->  2|D| = P  (double-collision bound attained)"
